#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_PIN 2
#define GPIO_PIN_3 3

int main(int argc, char *argv[])
{
	struct gpiod_chip *chip;
	struct gpiod_line *line;
	int ret;
	int i;

	chip = gpiod_chip_open("gpiochip0");
	if (chip == NULL) {
		fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
		return 1;
	}

	line = gpiod_chip_get_line(chip, GPIO_PIN);
	if (line == NULL) {
		fprintf(stderr, "gpiod_chip_get_line failed: %s\n", strerror(errno));
		return 1;
	}

	ret = gpiod_line_request_output(line, "my_output", GPIOD_LINE_REQUEST_NO_LOCK);
	if (ret < 0) {
		fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
		return 1;
	}

	line = gpiod_chip_get_line(chip, GPIO_PIN_3);
	if (line == NULL) {
		fprintf(stderr, "gpiod_chip_get_line failed: %s\n", strerror(errno));
		return 1;
	}

	ret = gpiod_line_request_output(line, "my_output", GPIOD_LINE_REQUEST_NO_LOCK);
	if (ret < 0) {
		fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
		return 1;
	}

	for (i = 0; i < 3; i++) {
		gpiod_line_set_value(line, 1);
		sleep(5);
		gpiod_line_set_value(line, 0);
		sleep(5);
	}

	gpiod_line_release(line);
	gpiod_chip_close(chip);

	return 0;
}

