    fd = open(MODEMDEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        perror(MODEMDEVICE);
        exit(-1);
    }

    /* save current port settings */
    tcgetattr(fd, &oldtio);

    /* set new port settings for canonical input processing */
    bzero(&newtio, sizeof(newtio));
    newtio.c_cflag = BAUDRATE | CS8 | CLOCAL | CREAD;
    newtio.c_iflag = IGNPAR;
    newtio.c_oflag = 0;

    /* set input mode (non-canonical, no echo,...) */
    newtio.c_lflag = 0;

    /* set newtio.c_cc[VMIN] = 1, so that read() returns after one character */
    newtio.c_cc[VMIN] = 1;

    /* set newtio.c_cc[VTIME] = 0, so that read() returns immediately */
    newtio.c_cc[VTIME] = 0;

    /* set the new settings */
    tcflush(fd, TCIFLUSH);
    tcsetattr(fd, TCSANOW, &newtio);

    /* set the modem control lines */
    ioctl(fd, TIOCMGET, &res);
    res |= TIOCM_DTR;
    res |= TIOCM_RTS;
    ioctl(fd, TIOCMSET, &res);

    /* read data from the device */
    while (TRUE) {
        res = read(fd, buf, 255);
        if (res < 0) {
            perror("read");
            exit(-1);
        }
        if (res == 0) {
            printf("No data\n");
            continue;
        }
        buf[res] = 0;
        printf("%s", buf);
    }

    /* restore the old port settings */
    tcsetattr(fd, TCSANOW, &oldtio);
    close(fd);
    return 0;
}

