#include <linux/i2c-dev.h>

#define MPU6050_I2C_ADDR 0x68
#define MPU6050_WHO_AM_I 0x75
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B

int main(int argc, char *argv[])
{
    int fd;
    int i;
    int ret;
    uint8_t whoami;
    uint8_t pwr_mgmt_1;
    uint8_t accel_xout_h;
    uint8_t accel_xout_l;
    uint8_t accel_yout_h;
    uint8_t accel_yout_l;
    uint8_t accel_zout_h;
    uint8_t accel_zout_l;
    uint8_t accel_xout;
    uint8_t accel_yout;
    uint8_t accel_zout;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1\n");
        return 1;
    }

    ret = ioctl(fd, I2C_SLAVE, MPU6050_I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return 1;
    }

    ret = read(fd, &whoami, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I\n");
        return 1;
    }

    if (whoami != 0x68) {
        fprintf(stderr, "WHO_AM_I is 0x%02x\n", whoami);
        return 1;
    }

    ret = write(fd, &pwr_mgmt_1, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to write PWR_MGMT_1\n");
        return 1;
    }

    for (i = 0; i < 100; i++) {
        ret = read(fd, &accel_xout_h, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to read ACCEL_XOUT_H\n");
            return 1;
        }

        ret = read(fd, &accel_xout_l, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to read ACCEL_XOUT_L\n");
            return 1;
        }

        ret = read(fd, &accel_yout_h, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to read ACCEL_YOUT_H\n");
            return 1;
        }

        ret = read(fd, &accel_yout_l, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to read ACCEL_YOUT_L\n");
            return 1;
        }

        ret = read(fd, &accel_zout_h, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to read ACCEL_ZOUT_H\n");
            return 1;
        }

        ret = read(fd, &accel_zout_l, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to read ACCEL_ZOUT_L\n");
            return 1;
        }

        accel_xout = (accel_xout_h << 8) | accel_xout_l;
        accel_yout = (accel_yout_h << 8) | accel_yout_l;
        accel_zout = (accel_zout_h << 8) | accel_zout_l;

        printf("accel_xout: %d\n", accel_xout);
        printf("accel_yout: %d\n", accel_yout);
        printf("accel_zout: %d\n", accel_zout);
    }

    close(fd);

    return 0;
}

