#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <sys/mman.h>
#include <errno.h>
#include <time.h>
#include <signal.h>

#define VIDEO_DEVICE "/dev/video0"
#define IMAGE_FILE "image.jpg"

#define CLEAR(x) memset(&(x), 0, sizeof(x))

struct buffer {
    void *start;
    size_t length;
};

struct buffer *buffers;

int fd;
int n_buffers;

void errno_exit(const char *s)
{
    fprintf(stderr, "%s error %d, %s\n", s, errno, strerror(errno));
    exit(EXIT_FAILURE);
}

void exit_handler(int sig)
{
    if (fd >= 0) {
        v4l2_buffer buf;
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        for (int i = 0; i < n_buffers; ++i) {
            buf.index = i;
            if (ioctl(fd, VIDIOC_QBUF, &buf) < 0)
                errno_exit("VIDIOC_QBUF");
        }
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0)
            errno_exit("VIDIOC_STREAMOFF");
    }
    if (fd >= 0)
        close(fd);
    if (buffers) {
        for (int i = 0; i < n_buffers; ++i)
            if (munmap(buffers[i].start, buffers[i].length) < 0)
                errno_exit("munmap");
        free(buffers);
    }
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[])
{
    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd < 0)
        errno_exit("open");

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0)
        errno_exit("VIDIOC_QUERYCAP");
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE))
        errno_exit("VIDIOC_QUERYCAP");
    if (!(cap.capabilities & V4L2_CAP_STREAMING))
        errno_exit("VIDIOC_QUERYCAP");

    struct v4l2_format fmt;
    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0)
        errno_exit("VIDIOC_S_FMT");
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_MJPEG)
        errno_exit("VIDIOC_S_FMT");
    if (fmt.fmt.pix.width != 640 || fmt.fmt.pix.height != 480)
        errno_exit("VIDIOC_S_FMT");

    struct v4l2_requestbuffers req;
    CLEAR(req);
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0)
        errno_exit("VIDIOC_REQBUFS");
    n_buffers = req.count;

    buffers = calloc(n_buffers, sizeof(*buffers));
    if (!buffers)
        errno_exit("calloc");

    for (int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0)
            errno_exit("VIDIOC_QUERYBUF");
        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED)
            errno_exit("mmap");
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0)
        errno_exit("VIDIOC_STREAMON");

    for (int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0)
            errno_exit("VIDIOC_QBUF");
    }

    struct timespec ts;
    ts.tv_sec = 1;
    ts.tv_nsec = 0;
    while (1) {
        nanosleep(&ts, NULL);
        struct v4l2_buffer buf;
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0)
            errno_exit("VIDIOC_DQBUF");
        FILE *f = fopen(IMAGE_FILE, "w");
        if (!f)
            errno_exit("fopen");
        fwrite(buffers[buf.index].start, buf.bytesused, 1, f);
        fclose(f);
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0)
            errno_exit("VIDIOC_QBUF");
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define VIDIOC_QUERYCAP		_IOWR('V', 0, struct v4l2_capability)
#define VIDIOC_ENUM_FMT		_IOWR('V', 5, struct v4l2_fmtdesc)
#define VIDIOC_S_FMT		_IOWR('V', 6, struct v4l2_format)
#define VIDIOC_G_FMT		_IOWR('V', 8, struct v4l2_format)
#define VIDIOC_REQBUFS		_IOWR('V', 80, struct v4l2_requestbuffers)
#define VIDIOC_QUERYBUF		_IOWR('V', 81, struct v4l2_buffer)
#define VIDIOC_QBUF		_IOWR('V', 83, struct v4l2_buffer)
#define VIDIOC_STREAMON		_IOW('V', 85, int)
#define VIDIOC_STREAMOFF	_IOW('V', 86, int)

#define CLEAR(x) memset(&(x), 0, sizeof(x))

struct buffer {
	void *start;
	size_t length;
};

int main(int argc, char **argv)
{
	struct v4l2_capability cap;
	struct v4l2_format fmt;
	struct v4l2_requestbuffers req;
	struct v4l2_buffer buf;
	struct buffer *buffers;
	int fd, n_buffers, i;
	char *dev_name = "/dev/video0";
	char *file_name = "image.jpg";

	if (argc > 1)
		file_name = argv[1];

	fd = open(dev_name, O_RDWR);
	if (fd < 0) {
		fprintf(stderr, "Cannot open %s: %d\n", dev_name, fd);
		return 1;
	}

	if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
		fprintf(stderr, "Cannot query %s: %d\n", dev_name, fd);
		return 1;
	}

	if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
		fprintf(stderr, "%s is not a video capture device\n", dev_name);
		return 1;
	}

	if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
		fprintf(stderr, "%s does not support streaming i/o\n", dev_name);
		return 1;
	}

	CLEAR(fmt);
	fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
	fmt.fmt.pix.width = 640;
	fmt.fmt.pix.height = 480;
	fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
	fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

	if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
		fprintf(stderr, "Cannot set format: %d\n", fd);
		return 1;
	}

	CLEAR(req);
	req.count = 4;
	req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
	req.memory = V4L2_MEMORY_MMAP;

	if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
		fprintf(stderr, "Cannot request buffer: %d\n", fd);
		return 1;
	}

	buffers = calloc(req.count, sizeof(*buffers));

	for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
		CLEAR(buf);
		buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
		buf.memory = V4L2_MEMORY_MMAP;
		buf.index = n_buffers;

		if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
			fprintf(stderr, "Cannot query buffer: %d\n", fd);
			return 1;
		}

		buffers[n_buffers].length = buf.length;
		buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

		if (buffers[n_buffers].start == MAP_FAILED) {
			fprintf(stderr, "Cannot map buffer: %d\n", fd);
			return 1;
		}
	}

	for (i = 0; i < n_buffers; ++i) {
		CLEAR(buf);
		buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
		buf.memory = V4L2_MEMORY_MMAP;
		buf.index = i;

		if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
			fprintf(stderr, "Cannot queue buffer: %d\n", fd);
			return 1;
		}
	}

	if (ioctl(fd, VIDIOC_STREAMON, &fmt.type) < 0) {
		fprintf(stderr, "Cannot start capture: %d\n", fd);
		return 1;
	}

	for (;;) {
		fd_set fds;
		struct timeval tv;
		int r;

		FD_ZERO(&fds);
		FD_SET(fd, &fds);

		tv.tv_sec = 2;
		tv.tv_usec = 0;

		r = select(fd + 1, &fds, NULL, NULL, &tv);

		if (r == -1) {
			perror("select");
			return 1;
		}

		if (r == 0) {
			fprintf(stderr, "select timeout\n");
			return 1;
		}

		CLEAR(buf);
		buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
		buf.memory = V4L2_MEMORY_MMAP;

		if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
			fprintf(stderr, "Cannot dequeue buffer: %d\n", fd);
			return 1;
		}

		FILE *f = fopen(file_name, "w");
		if (f == NULL) {
			fprintf(stderr, "Cannot open file: %s\n", file_name);
			return 1;
		}

		fwrite(buffers[buf.index].start, buf.bytesused, 1, f);
		fclose(f);

		if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
			fprintf(stderr, "Cannot queue buffer: %d\n", fd);
			return 1;
		}

		if (ioctl(fd, VIDIOC_STREAMOFF, &fmt.type) < 0) {
			fprintf(stderr, "Cannot stop capture: %d\n", fd);
			return 1;
		}

		break;
	}

	for (i = 0; i < n_buffers; ++i)
		munmap(buffers[i].start, buffers[i].length);

	free(buffers);

	close(fd);

	return 0;
}

#include <stdio.h>
