#define GPIO_PIN 17

int main(int argc, char *argv[])
{
	struct gpiod_chip *chip;
	struct gpiod_line *line;
	int ret;

	if (argc != 2) {
		fprintf(stderr, "Usage: %s <on|off>\n", argv[0]);
		exit(EXIT_FAILURE);
	}

	chip = gpiod_chip_open("gpiochip0");
	if (!chip) {
		fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
		exit(EXIT_FAILURE);
	}

	line = gpiod_chip_get_line(chip, GPIO_PIN);
	if (!line) {
		fprintf(stderr, "gpiod_chip_get_line: %s\n", strerror(errno));
		exit(EXIT_FAILURE);
	}

	if (strcmp(argv[1], "on") == 0) {
		ret = gpiod_line_request_output(line, "gpio-test", 0);
		if (ret < 0) {
			fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
			exit(EXIT_FAILURE);
		}
		gpiod_line_set_value(line, 1);
	} else if (strcmp(argv[1], "off") == 0) {
		ret = gpiod_line_request_output(line, "gpio-test", 0);
		if (ret < 0) {
			fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
			exit(EXIT_FAILURE);
		}
		gpiod_line_set_value(line, 0);
	} else {
		fprintf(stderr, "Usage: %s <on|off>\n", argv[0]);
		exit(EXIT_FAILURE);
	}

	gpiod_line_release(line);
	gpiod_chip_close(chip);

	return 0;
}

