#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define LED_PIN 18
#define LED_COUNT 100

int main(int argc, char *argv[])
{
    int i;
    int err;
    int gpio;
    int *leds;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return 1;
    }

    gpio = gpioOpen(LED_PIN, PI_OUTPUT, PI_OFF);
    if (gpio < 0) {
        fprintf(stderr, "gpioOpen failed\n");
        return 1;
    }

    leds = malloc(LED_COUNT * sizeof(int));
    if (leds == NULL) {
        fprintf(stderr, "malloc failed\n");
        return 1;
    }

    for (i = 0; i < LED_COUNT; i++) {
        leds[i] = 0;
    }

    for (i = 0; i < LED_COUNT; i++) {
        leds[i] = 0x0000FF;
        gpioWrite(gpio, leds[i]);
        usleep(50000);
    }

    for (i = 0; i < LED_COUNT; i++) {
        leds[i] = 0x00FF00;
        gpioWrite(gpio, leds[i]);
        usleep(50000);
    }

    for (i = 0; i < LED_COUNT; i++) {
        leds[i] = 0xFF0000;
        gpioWrite(gpio, leds[i]);
        usleep(50000);
    }

    gpioWrite(gpio, PI_OFF);
    gpioClose(gpio);
    free(leds);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
