            return 1;
        }

        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_set_value failed: %s\n", strerror(errno));
            return 1;
        }

        ret = gpiod_line_set_value(line_17, 1);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_set_value failed: %s\n", strerror(errno));
            return 1;
        }

        ret = gpiod_line_set_value(line_18, 1);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_set_value failed: %s\n", strerror(errno));
            return 1;
        }

        ret = gpiod_line_set_value(line_22, 1);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_set_value failed: %s\n", strerror(errno));
